import networkx as nx

def is_adjacent(p1, p2):
    """Checks if two points are adjacent in the King's graph."""
    x1, y1 = p1
    x2, y2 = p2
    return abs(x1 - x2) <= 1 and abs(y1 - y2) <= 1 and (x1 != x2 or y1 != y2)

N = 9 # Testing on 9x9 grid

# Define C_R: (i, j) where i=1 mod 3, j=1 mod 3
C_R = []
for i in range(1, N + 1):
    for j in range(1, N + 1):
        if i % 3 == 1 and j % 3 == 1:
            C_R.append((i, j))

# Define C_B: (i, j) where i=2 mod 3, j=2 mod 3
C_B = []
for i in range(1, N + 1):
    for j in range(1, N + 1):
        if i % 3 == 2 and j % 3 == 2:
            C_B.append((i, j))

print(f"Size of C_R: {len(C_R)}")
print(f"Size of C_B: {len(C_B)}")

# Verification 1: Check if C_R is an Independent Set (Internal edges within C_R)
graph_R = nx.Graph()
R_coords = set(C_R)
for i in range(len(C_R)):
    for j in range(i + 1, len(C_R)):
        p1 = C_R[i]
        p2 = C_R[j]
        if is_adjacent(p1, p2):
            print(f"ERROR: C_R is NOT independent. Edge found between {p1} and {p2}")
            # For the purpose of this check, we can stop if we find an error, but we know based on theory this shouldn't happen.
            break
    else:
        # Inner loop completed without break
        pass
else:
    print("Verification 1a: C_R is an Independent Set.")


# Verification 2: Check if C_B is an Independent Set (Internal edges within C_B)
graph_B = nx.Graph()
B_coords = set(C_B)
for i in range(len(C_B)):
    for j in range(i + 1, len(C_B)):
        p1 = C_B[i]
        p2 = C_B[j]
        if is_adjacent(p1, p2):
            print(f"ERROR: C_B is NOT independent. Edge found between {p1} and {p2}")
            break
    else:
        pass
else:
    print("Verification 1b: C_B is an Independent Set.")


# Verification 3 & 4: Check for a perfect matching between C_R and C_B
G = nx.Graph()
nodes = C_R + C_B
G.add_nodes_from(nodes)

# Add edges only between C_R and C_B
for p_r in C_R:
    for p_b in C_B:
        if is_adjacent(p_r, p_b):
            G.add_edge(p_r, p_b)

# Find the maximum matching
# nx.max_weight_matching is suitable, but since all edges have weight 1, we can use standard matching
matching = nx.bipartite.maximum_matching(G, top_nodes=C_R)
matching_size = len(matching) // 2 # Since it returns edges as (u, v) tuples, and keys are nodes

print(f"Total nodes in the bipartite graph: {len(nodes)}")
print(f"Maximum matching size found: {matching_size}")
print(f"Is the matching perfect (size equals min(|C_R|, |C_B|))? {matching_size == min(len(C_R), len(C_B))}")
